const videoID=()=>globalThis.crypto?.randomUUID?.()||`video-${Date.now()}-${Math.random().toString(36).slice(2)}`;
export function safeVideoURL(value){if(typeof value!=='string'||value.length>4096)return '';try{const u=new URL(value.trim());if(u.protocol!=='https:'||u.username||u.password||!u.hostname.includes('.'))return '';return u.href;}catch{return '';}}
export function ensureVideoData(p){p.videoJobs??=[];p.videoResults??=[];p.videoDraft??={source:'project',prompt:'',duration:20,format:p.format||'9:16',resolution:p.resolution||'1080P',mode:'text',referenceIds:[],firstFrameId:'',lastFrameId:'',notes:''};return p.videoDraft;}
export function videoPromptText(draft,fps=24){const body=String(draft.prompt||'').replace(/^(画面规格：|Output requirements:|画幅目标：)[^\n]*\n*/,'').trim();if(!body)return '';return `画幅目标：${draft.format} · 分辨率目标：${draft.resolution} · ${fps}fps · 时长目标：${draft.duration}秒\n\n${body}`;}
export function createVideoPlan(p,draft,{fps=24}={}){if((p.videoJobs||[]).length>=100)throw Error('本项目最多保存100个视频计划，请先导出整理。');const prompt=videoPromptText(draft,fps);if(!prompt||prompt.length>24000)throw Error('请填写有效的视频提示词，最多24000字。');const duration=Number(draft.duration);if(!Number.isFinite(duration)||duration<1||duration>120)throw Error('生成目标时长应为1—120秒。');if(!['text','reference','frames'].includes(draft.mode))throw Error('请选择生成方式。');if(typeof draft.format!=='string'||draft.format.length>30||typeof draft.resolution!=='string'||draft.resolution.length>30)throw Error('画面目标设置不正确。');const images=p.references.filter(r=>r.type==='image'),known=new Set(images.map(r=>r.id)),refs=[...new Set((draft.referenceIds||[]).filter(id=>known.has(id)))];if(draft.mode==='reference'&&!refs.length)throw Error('请先选择参考图片，或改为文生视频。');if(draft.mode==='frames'&&(!known.has(draft.firstFrameId)||!known.has(draft.lastFrameId)))throw Error('首尾帧模式需要选择两张已有图片。');return {id:videoID(),name:`视频计划 ${(p.videoJobs||[]).length+1}`,status:'draft',origin:'local-plan',provider:'待接入',createdAt:Date.now(),source:draft.source,prompt,duration,format:draft.format,resolution:draft.resolution,fps,mode:draft.mode,referenceIds:draft.mode==='reference'?refs:draft.mode==='frames'?[draft.firstFrameId,draft.lastFrameId]:[],notes:String(draft.notes||'').slice(0,2000),submittedAt:null,remoteTaskId:null};}
export function importVideoResult(p,{title,url}){const safe=safeVideoURL(url);if(!safe)throw Error('请输入有效的 HTTPS 视频链接，不支持脚本、账号密码或本地临时地址。');if((p.videoResults||[]).length>=100)throw Error('本项目最多保存100个视频链接。');return {id:videoID(),title:String(title||'导入的视频').trim().slice(0,100)||'导入的视频',url:safe,origin:'imported',status:'imported',createdAt:Date.now()};}
export function validateVideoData(p){for(const k of ['videoJobs','videoResults'])if(p[k]!==undefined&&(!Array.isArray(p[k])||p[k].length>100))throw Error('视频项目列表格式不正确。');if(p.videoDraft){const d=p.videoDraft;if(typeof d!=='object'||typeof d.source!=='string'||typeof d.mode!=='string'||typeof d.format!=='string'||typeof d.resolution!=='string'||typeof d.prompt!=='string'||d.prompt.length>24000||!Array.isArray(d.referenceIds)||d.referenceIds.length>100||!d.referenceIds.every(x=>typeof x==='string')||!Number.isFinite(Number(d.duration)))throw Error('视频草稿格式不正确。');}for(const j of p.videoJobs||[])if(!j||typeof j.id!=='string'||j.status!=='draft'||j.origin!=='local-plan'||typeof j.prompt!=='string'||j.prompt.length>24500||!Number.isFinite(Number(j.duration))||!Array.isArray(j.referenceIds)||j.remoteTaskId)throw Error('视频计划格式不正确，不能把本地计划标记为已提交。');for(const r of p.videoResults||[])if(!r||typeof r.id!=='string'||typeof r.title!=='string'||r.origin!=='imported'||r.status!=='imported'||!safeVideoURL(r.url))throw Error('视频结果链接格式不正确。');}
